/**
 * Creates a PointsBVH range query function that returns accumulated weighted normals.
 *
 * This function is designed for constraint systems where particles collide with
 * multiple nearby points. Instead of responding to a single closest point (which
 * causes jittery behavior), it accumulates normals from ALL penetrating points
 * with quadratic weighting by penetration depth.
 *
 * Uses the TSL Fn() pattern which:
 * 1. Accesses storage buffers via .element() - generates NodeBuffer_XXX.value[i] syntax
 * 2. Avoids ptr<storage, ...> in function signatures
 * 3. Works on Safari/Firefox WebGPU
 *
 * @param {StorageBufferNode} bvhIndexBuffer - Storage buffer for point indices (uint)
 * @param {StorageBufferNode} bvhPositionBuffer - Storage buffer for point positions (vec3f)
 * @param {StorageBufferNode} bvhNodeBuffer - Storage buffer for BVH nodes (flat f32 array)
 * @returns {Function} A TSL function that computes range query with weighted normals
 */
export function createPointsBVHRangeQueryFn(bvhIndexBuffer: StorageBufferNode, bvhPositionBuffer: StorageBufferNode, bvhNodeBuffer: StorageBufferNode): Function;
/**
 * Computes the squared distance from a point to an AABB.
 */
export const distanceSqToBoundsWGSL: any;
